’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬
abstract class DownloadHiddifyCoreTask : DefaultTask() {

    /**
     * Gradle 9 removed `Project.exec`/`Project.javaexec`; injected
     * `ExecOperations` is the supported replacement and is configuration
     * cache friendly.
     */
    @get:Inject
    abstract val execOperations: ExecOperations

    @get:Input
    abstract val coreArchiveUrl: Property<String>

    /** Refreshes undersized AARs, including older incompatible API versions. */
    @get:Input
    abstract val minimumAarBytes: Property<Long>

    @get:Internal
    abstract val workingDirectory: DirectoryProperty

    @get:OutputFile
    abstract val coreAar: RegularFileProperty

    @get:OutputFile
    abstract val coreVersionStamp: RegularFileProperty

    @TaskAction
    fun obtainCoreAar() {
        val target = coreAar.get().asFile
        val minimumBytes = minimumAarBytes.get()

        val versionStamp = coreVersionStamp.get().asFile
        val requestedCore = coreArchiveUrl.get()
        if (target.exists() && target.length() > minimumBytes &&
            versionStamp.exists() && versionStamp.readText().trim() == requestedCore
        ) {
            logger.lifecycle("hiddify-core.aar matches the requested version; skipping download.")
            return
        }
        val workDirectory = workingDirectory.get().asFile
        workDirectory.mkdirs()

        val archive = File(workDirectory, "hiddify-lib-android.tar.gz")
        val extractionDirectory = File(workDirectory, "extracted")
        extractionDirectory.deleteRecursively()
        extractionDirectory.mkdirs()

        try {
            logger.lifecycle("Downloading ${coreArchiveUrl.get()}")
            download(coreArchiveUrl.get(), archive)

            // The release ships a tar.gz, so the AAR has to be unpacked first.
            // Windows and macOS both bundle a `tar` that understands -xzf / -C.
            execOperations.exec {
                commandLine("tar", "-xzf", archive.absolutePath, "-C", extractionDirectory.absolutePath)
            }.assertNormalExitValue()

            val extractedAar = extractionDirectory
                .walkTopDown()
                .firstOrNull { it.isFile && it.extension.equals("aar", ignoreCase = true) }
                ?: throw GradleException("No .aar file found inside ${archive.name}.")

            target.parentFile?.mkdirs()
            extractedAar.copyTo(target, overwrite = true)
            versionStamp.parentFile?.mkdirs()
            versionStamp.writeText(requestedCore)
            logger.lifecycle("hiddify-core.aar prepared (${target.length()} bytes).")
        } catch (e: Exception) {
            if (target.exists() && target.length() > minimumBytes &&
                versionStamp.exists() && versionStamp.readText().trim() == requestedCore
            ) {
                logger.warn("Could not refresh the matching Hiddify core archive; using the local copy.")
            } else {                throw GradleException("Unable to obtain hiddify-core.aar: ${e.message}", e)
            }
        } finally {
            archive.delete()
            extractionDirectory.deleteRecursively()
        }
    }

    private fun download(url: String, destination: File) {
        val connectTimeoutMillis = 30_000
        val readTimeoutMillis = 300_000

        val connection = URL(url).openConnection()
        connection.connectTimeout = connectTimeoutMillis
        connection.readTimeout = readTimeoutMillis
        connection.getInputStream().use { input ->
            FileOutputStream(destination).use { output -> input.copyTo(output) }
        }
    }
}

val downloadHiddifyCore = tasks.register<DownloadHiddifyCoreTask>("downloadHiddifyCore") {
    description = "Ensures app/libs/hiddify-core.aar exists before the app is built."
    group = "build setup"
    coreArchiveUrl.set(
        "https://github.com/hiddify/hiddify-core/releases/download/v4.1.0/hiddify-lib-android.tar.gz"
    )
    minimumAarBytes.set(110_000_000L)
    coreAar.set(layout.projectDirectory.file("libs/hiddify-core.aar"))
    coreVersionStamp.set(layout.buildDirectory.file("hiddify-core/core-version.txt"))
    workingDirectory.set(layout.buildDirectory.dir("hiddify-core"))
}

tasks.matching { it.name == "preBuild" }.configureEach {
    dependsOn(downloadHiddifyCore)
}

